//! Work Management domain entities: Workspace and Project.

use serde::{Deserialize, Serialize};

/// Opaque workspace identifier, a UUIDv7 text value (36 chars, e.g.
/// `550e8400-e29b-7d73-9b9c-000000000000`). Generated by the application;
/// callers must not infer ordering or authorization from it.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct WorkspaceId(String);

impl WorkspaceId {
    /// Build from a validated UUIDv7 text value.
    pub fn new(value: impl Into<String>) -> Result<Self, ParseError> {
        let s = value.into();
        if uuid::Uuid::parse_str(&s).is_err() {
            return Err(ParseError(s));
        }
        Ok(Self(s))
    }

    /// Generate a fresh UUIDv7 workspace identifier.
    pub fn new_v7() -> Self {
        Self(uuid::Uuid::now_v7().to_string())
    }

    /// Borrow the raw text.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParseError(String);

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "invalid workspace identifier: {}", self.0)
    }
}

impl std::error::Error for ParseError {}

/// A workspace is the top-level tenancy boundary for the workbench.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Workspace {
    pub id: WorkspaceId,
    pub name: String,
}

/// A project lives inside exactly one workspace.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Project {
    pub id: ProjectId,
    pub workspace_id: WorkspaceId,
    pub name: String,
}

/// Opaque project identifier, a UUIDv7 text value.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct ProjectId(String);

impl ProjectId {
    pub fn new(value: impl Into<String>) -> Result<Self, ParseError> {
        let s = value.into();
        if uuid::Uuid::parse_str(&s).is_err() {
            return Err(ParseError(s));
        }
        Ok(Self(s))
    }

    pub fn new_v7() -> Self {
        Self(uuid::Uuid::now_v7().to_string())
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}
